// Golden renders of the Web engine (owner: host; tools/make-goldens.js,
// native/engine/SPEC.md §18.4). Runs in a hidden Electron window and renders
// with OfflineAudioContext ONLY (no device, silent), using the Web engine's
// own code: engine.js Deck, FxUnit and AudioEngine (AudioContext aliased to
// the OfflineAudioContext of the case), raw AudioBufferSourceNodes with the
// settings engine.js gives them, and the real pitch-worklet.js in an
// AudioWorklet. Parameter moves happen at exact render-quantum frames
// through OfflineAudioContext.suspend(t). Every input is generated by a
// seeded xorshift32 (documented in each JSON, so a native test can
// regenerate it); Math.random is replaced by the same generator before the
// Web engine builds its reverb impulses and its noise buffer, and those
// buffers are saved next to the cases that use them.
//
// Suites: strip (Deck: EQ / filter / trim / fader), master (AudioEngine
// master chain, crossfader), limiter (DynamicsCompressor of engine.js),
// source (AudioBufferSourceNode rates, file rate != context rate, loops,
// ends, V.BRAKE / BACKSPIN voices), fxunit (every FxUnit type), color (every
// Color FX type + noise), wsola (pitch-worklet.js), decode (decodeAudioData
// of generated files).
import { Deck, FxUnit, AudioEngine } from '../../src/js/engine.js';

const SR = 48000;
const Q = 128;  // render quantum: suspend() points and k-rate parameters
const params = new URLSearchParams(location.search);
const only = (params.get('suites') || '').split(',').map((s) => s.trim()).filter(Boolean);
const quick = params.get('quick') === '1';
const errors = [];
const UA = navigator.userAgent;

// ---------------------------------------------------------------------------
// Seeded generator: xorshift32, rand() = x / 2^32 in [0, 1) (the native
// engine's quantizer uses the same generator: SPEC.md §7.3).
// ---------------------------------------------------------------------------
function xorshift(seed) {
  let x = seed >>> 0 || 0x9e3779b9;
  return () => {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    return x / 4294967296;
  };
}

// ---------------------------------------------------------------------------
// Signals (frames at SR unless said otherwise)
// ---------------------------------------------------------------------------
const sec = (s, rate = SR) => Math.round(s * rate);
const qframes = (s) => Math.round((s * SR) / Q) * Q;  // a time on the render-quantum grid

function noise(frames, seed, amp) {
  const r = xorshift(seed);
  const a = new Float32Array(frames);
  for (let i = 0; i < frames; i++) a[i] = (r() * 2 - 1) * amp;
  return a;
}
function stereoNoise(frames, amp = 0.25) {
  return [noise(frames, 0x1234567, amp), noise(frames, 0x7654321, amp)];
}
// "Music-like": harmonics of 110 Hz with a slow envelope, a high sine, a little noise.
function musicLike(frames, rate = SR, seed = 0xabcdef) {
  const r = xorshift(seed);
  const L = new Float32Array(frames);
  const R = new Float32Array(frames);
  for (let i = 0; i < frames; i++) {
    const t = i / rate;
    const env = 0.6 + 0.4 * Math.sin(2 * Math.PI * 1.7 * t);
    let v = 0;
    for (let h = 1; h <= 6; h++) v += Math.sin(2 * Math.PI * 110 * h * t + h) / h;
    const n = (r() * 2 - 1) * 0.05;
    L[i] = 0.25 * env * v + 0.05 * Math.sin(2 * Math.PI * 3520 * t) + n;
    R[i] = 0.25 * env * v * 0.9 + 0.05 * Math.sin(2 * Math.PI * 3150 * t + 1) - n;
  }
  return [L, R];
}
// FX input: an impulse, a noise burst, a sine + noise section, then silence for the tails.
function fxInput(frames) {
  const r = xorshift(0x5eed);
  const L = new Float32Array(frames);
  const R = new Float32Array(frames);
  L[sec(0.05)] = 0.9;
  R[sec(0.05)] = 0.9;
  for (let i = sec(0.5); i < sec(0.6); i++) {
    L[i] = (r() * 2 - 1) * 0.5;
    R[i] = (r() * 2 - 1) * 0.5;
  }
  for (let i = sec(1.0); i < Math.min(frames, sec(2.0)); i++) {
    const t = i / SR;
    const n = (r() * 2 - 1) * 0.1;
    L[i] = 0.3 * Math.sin(2 * Math.PI * 440 * t) + n;
    R[i] = 0.3 * Math.sin(2 * Math.PI * 660 * t) + n;
  }
  return [L, R];
}
function sineBursts(frames, levels, onSec, offSec, freq) {
  const L = new Float32Array(frames);
  const R = new Float32Array(frames);
  let pos = sec(0.05);
  for (const lv of levels) {
    for (let i = pos; i < Math.min(frames, pos + sec(onSec)); i++) {
      const v = lv * Math.sin((2 * Math.PI * freq * (i - pos)) / SR);
      L[i] = v;
      R[i] = v;
    }
    pos += sec(onSec + offSec);
  }
  return [L, R];
}

// ---------------------------------------------------------------------------
// WAV (float32 or PCM), AudioBuffer helpers
// ---------------------------------------------------------------------------
function wav(channels, rate, format = 'f32') {
  const nch = channels.length;
  const frames = channels[0].length;
  const bps = format === 'f32' ? 4 : format === 's24' ? 3 : 2;
  const dataBytes = frames * nch * bps;
  const buf = new ArrayBuffer(44 + dataBytes);
  const dv = new DataView(buf);
  const str = (o, s) => {
    for (let i = 0; i < s.length; i++) dv.setUint8(o + i, s.charCodeAt(i));
  };
  str(0, 'RIFF');
  dv.setUint32(4, 36 + dataBytes, true);
  str(8, 'WAVE');
  str(12, 'fmt ');
  dv.setUint32(16, 16, true);
  dv.setUint16(20, format === 'f32' ? 3 : 1, true);
  dv.setUint16(22, nch, true);
  dv.setUint32(24, rate, true);
  dv.setUint32(28, rate * nch * bps, true);
  dv.setUint16(32, nch * bps, true);
  dv.setUint16(34, bps * 8, true);
  str(36, 'data');
  dv.setUint32(40, dataBytes, true);
  let o = 44;
  for (let i = 0; i < frames; i++) {
    for (let c = 0; c < nch; c++) {
      const v = channels[c][i];
      if (format === 'f32') {
        dv.setFloat32(o, v, true);
      } else if (format === 's24') {
        const s = Math.max(-8388608, Math.min(8388607, Math.round(v * 8388607)));
        dv.setUint8(o, s & 255);
        dv.setUint8(o + 1, (s >> 8) & 255);
        dv.setUint8(o + 2, (s >> 16) & 255);
      } else {
        dv.setInt16(o, Math.max(-32768, Math.min(32767, Math.round(v * 32767))), true);
      }
      o += bps;
    }
  }
  return new Uint8Array(buf);
}
function channelsOf(ab) {
  const out = [];
  for (let c = 0; c < ab.numberOfChannels; c++) out.push(ab.getChannelData(c).slice());
  return out;
}
function bufferFrom(ctx, chans, rate = ctx.sampleRate) {
  const b = ctx.createBuffer(chans.length, chans[0].length, rate);
  chans.forEach((d, c) => b.copyToChannel(d, c));
  return b;
}
function playInto(ctx, chans, dest, rate) {
  const src = ctx.createBufferSource();
  src.buffer = bufferFrom(ctx, chans, rate);
  src.connect(dest);
  src.start(0);
  return src;
}

// An engine.js AudioEngine built on this OfflineAudioContext (its constructor
// calls `new AudioContext()`). OfflineAudioContext has no MediaStream
// destination (the recorder tap): a silent gain stands in. The WSOLA worklet
// is not loaded (the decks are idle in these graphs, their transposed path
// is muted).
function makeEngine(ctx) {
  if (!ctx.createMediaStreamDestination) ctx.createMediaStreamDestination = () => Object.assign(ctx.createGain(), { stream: null });
  const savedCtx = window.AudioContext;
  const savedLoad = AudioEngine.prototype._loadPitchWorklet;
  window.AudioContext = function OfflineAlias() {
    return ctx;
  };
  AudioEngine.prototype._loadPitchWorklet = async function () {};
  try {
    return new AudioEngine();
  } finally {
    window.AudioContext = savedCtx;
    AudioEngine.prototype._loadPitchWorklet = savedLoad;
  }
}

// ---------------------------------------------------------------------------
// Case runner
// ---------------------------------------------------------------------------
let caseCount = 0;
async function runCase(suite, name, def) {
  if (only.length && !only.includes(suite)) return;
  const rate = def.rate || SR;
  const channels = def.channels || 2;
  const frames = def.frames;
  try {
    const ctx = new OfflineAudioContext(channels, frames, rate);
    const meta = {
      suite,
      case: name,
      sampleRate: rate,
      channels,
      frames,
      chromium: UA,
      engineJs: def.engineJs || '',
      graph: def.graph || '',
      input: `${name}.input.wav`,
      inputDesc: def.inputDesc || '',
      setup: [],
      events: [],
      files: {},
      notes: def.notes || '',
      tolerance: def.tolerance || 'residual < -80 dBFS at tempo 1 (SPEC.md §18.3)'
    };
    const env = await def.build(ctx, meta);  // { input: [L, R], events: [{frame, call, args, run}], files: {name: [chans, rate]} }
    // Events on the render-quantum grid, grouped per frame (one suspend per frame).
    const byFrame = new Map();
    for (const ev of env.events || []) {
      if (ev.frame % Q !== 0) throw new Error(`event at frame ${ev.frame} is not on the ${Q}-frame grid`);
      meta.events.push({ frame: ev.frame, time: ev.frame / rate, call: ev.call, args: ev.args });
      if (ev.frame === 0) {
        ev.run();
        continue;
      }
      if (!byFrame.has(ev.frame)) byFrame.set(ev.frame, []);
      byFrame.get(ev.frame).push(ev);
    }
    for (const [frame, list] of byFrame) {
      ctx.suspend(frame / rate).then(() => {
        for (const ev of list) ev.run();
        ctx.resume();
      });
    }
    const out = await ctx.startRendering();
    const dir = suite;
    for (const [fname, [chans, frate, fmt]] of Object.entries(env.files || {})) {
      await window.goldens.write(`${dir}/${fname}`, wav(chans, frate, fmt || 'f32'));
      meta.files[fname.replace(/\.wav$/, '')] = `${dir}/${fname}`;
    }
    if (env.inputFile) {
      meta.input = env.inputFile.name;
      await window.goldens.write(`${dir}/${env.inputFile.name}`, env.inputFile.bytes);
    } else {
      await window.goldens.write(`${dir}/${name}.input.wav`, wav(env.input, env.inputRate || rate));
    }
    meta.channels = out.numberOfChannels;
    meta.sampleRate = out.sampleRate;
    meta.frames = out.length;
    await window.goldens.write(`${dir}/${name}.wav`, wav(channelsOf(out), out.sampleRate));
    await window.goldens.write(`${dir}/${name}.json`, JSON.stringify(meta, null, 1));
    await window.goldens.addCase({ suite, case: name, frames: out.length, note: def.short || '' });
    caseCount++;
  } catch (e) {
    errors.push(`${suite}/${name}: ${e && e.stack ? e.stack : e}`);
  }
}

// A call recorded in the JSON and run at its frame.
const at = (frame, call, args, run) => ({ frame, call, args, run });

// ---------------------------------------------------------------------------
// strip: engine.js Deck channel strip (TRIM -> EQ -> FILTER -> post -> fader -> xf -> dryOut)
// ---------------------------------------------------------------------------
async function suiteStrip() {
  const step = qframes(0.25);  // 12032 frames: one move every ~0.25 s, on the quantum grid
  const graph = 'input -> deck.trim -> eqLow -> eqMid -> eqHigh -> filter -> post -> fader (volume^2 = 0.7225) -> xf (1) -> dryOut (1) -> destination';
  const deckCase = (name, moves, short) =>
    runCase('strip', name, {
      frames: step * (moves.length + 2),
      engineJs: 'Deck (src/js/engine.js)',
      graph,
      inputDesc: 'stereo white noise +-0.25, xorshift32 seeds 0x1234567 (L) / 0x7654321 (R)',
      short,
      build: async (ctx) => {
        const deck = new Deck(ctx, ctx.destination, 0);
        const input = stereoNoise(step * (moves.length + 2));
        playInto(ctx, input, deck.trim);
        const events = moves.map(([call, args], i) => at(step * (i + 1), `deck.${call}`, args, () => deck[call](...args)));
        return { input, events };
      }
    });
  const bands = ['low', 'mid', 'high'];
  for (const b of bands) {
    const vals = quick ? [1, -1, 0] : [0.5, 1, -0.25, -1, 0.75, 0];
    await deckCase(`eq_${b}_sweep`, vals.map((v) => ['setEq', [b, v]]), `setEq('${b}') ${vals.join(' ')}`);
  }
  await deckCase('eq_kill_all', [
    ['setEq', ['low', -1]], ['setEq', ['mid', -1]], ['setEq', ['high', -1]], ['setEq', ['low', 0]], ['setEq', ['mid', 0.5]], ['setEq', ['high', 0]]
  ], 'kills and back');
  const fvals = quick ? [-1, 0.5, 0] : [-1, -0.6, -0.3, -0.035, 0.02, 0.3, 0.6, 1, 0];
  await deckCase('filter_sweep', fvals.map((v) => ['setFilter', [v]]), `setFilter ${fvals.join(' ')} (dead zone 0.04)`);
  await deckCase('trim_steps', [-1, -0.5, 0.25, 1, 0].map((v) => ['setTrim', [v]]), 'setTrim (4^v, tau 10 ms)');
  await deckCase('fader_steps', [0, 0.3, 1, 0.85].map((v) => ['setVolume', [v]]), 'setVolume (v^2, tau 10 ms)');
}

// ---------------------------------------------------------------------------
// master + limiter: engine.js AudioEngine
// ---------------------------------------------------------------------------
async function suiteMaster() {
  const step = qframes(0.25);
  const graph =
    'input -> engine.masterGain (0.9) -> dryComp (1) -> postBus -> mFilter -> limiter (DynamicsCompressor -3 dB, knee 0, ratio 12, attack 0.002, release 0.15) -> destination';
  const engCase = (name, moves, short) =>
    runCase('master', name, {
      frames: step * (moves.length + 2),
      engineJs: 'AudioEngine (src/js/engine.js), AudioContext aliased to this OfflineAudioContext',
      graph,
      inputDesc: 'stereo white noise +-0.25, xorshift32 seeds 0x1234567 / 0x7654321',
      notes: 'Math.random = xorshift32(0xC0FFEE) while the engine is built (impulses, noise buffer); the decks are idle.',
      short,
      build: async (ctx) => {
        Math.random = xorshift(0xc0ffee);
        const engine = makeEngine(ctx);
        const input = stereoNoise(step * (moves.length + 2));
        playInto(ctx, input, engine.masterGain);
        const events = moves.map(([call, args], i) => at(step * (i + 1), `engine.${call}`, args, () => engine[call](...args)));
        return { input, events };
      }
    });
  await engCase('volume_steps', [0.5, 1, 0.2, 0.9].map((v) => ['setMasterVolume', [v]]), 'setMasterVolume');
  await engCase('filter_sweep', [-1, -0.4, -0.02, 0.4, 1, 0].map((v) => ['setMasterFilter', [v]]), 'setMasterFilter');
  // The crossfader through two decks' strips (side A: deck 0, side B: deck 1).
  await runCase('master', 'crossfader_curve', {
    frames: step * 7,
    engineJs: 'AudioEngine (src/js/engine.js)',
    graph: 'noise A -> decks[0].trim, noise B -> decks[1].trim -> strips -> xf (mix curve) -> dryOut -> masterGain -> ... -> limiter -> destination',
    inputDesc: 'L/R of the input file: deck 0 gets [L, L] (seed 0x1234567), deck 1 gets [R, R] (seed 0x7654321), noise +-0.25',
    notes: 'Math.random = xorshift32(0xC0FFEE) while the engine is built.',
    short: 'setCrossfader 0 .25 .5 .75 1',
    build: async (ctx) => {
      Math.random = xorshift(0xc0ffee);
      const engine = makeEngine(ctx);
      const input = stereoNoise(step * 7);
      playInto(ctx, [input[0], input[0]], engine.decks[0].trim);
      playInto(ctx, [input[1], input[1]], engine.decks[1].trim);
      const events = [0, 0.25, 0.5, 0.75, 1].map((x, i) => at(step * (i + 1), 'engine.setCrossfader', [x], () => engine.setCrossfader(x)));
      return { input, events };
    }
  });
}

async function suiteLimiter() {
  const graph = 'input -> engine.limiter (DynamicsCompressor: threshold -3 dB, knee 0, ratio 12, attack 0.002 s, release 0.15 s) -> destination';
  const limCase = (name, frames, input, inputDesc, short) =>
    runCase('limiter', name, {
      frames,
      engineJs: 'AudioEngine.limiter (src/js/engine.js)',
      graph,
      inputDesc,
      notes: 'The DynamicsCompressor adds a 6 ms pre-delay (look-ahead): the output is late by 288 frames at 48 kHz.',
      short,
      build: async (ctx) => {
        Math.random = xorshift(0xc0ffee);
        const engine = makeEngine(ctx);
        playInto(ctx, input, engine.limiter);
        return { input, events: [] };
      }
    });
  await limCase('sine_bursts', sec(4.2), sineBursts(sec(4.2), [0.3, 0.7, 1.0, 1.5, 2.0, 3.0], 0.3, 0.35, 1000),
    '1 kHz sine bursts 0.3 s on / 0.35 s off at 0.3 0.7 1 1.5 2 3 (from 0.05 s)', 'bursts 0.3 .. 3.0');
  {
    const f = sec(3);
    const n = stereoNoise(f, 1);
    for (let i = 0; i < f; i++) {
      const g = i < sec(1) ? 0.1 : i < sec(2) ? 2.0 : 0.1;
      n[0][i] *= g;
      n[1][i] *= g;
    }
    await limCase('noise_steps', f, n, 'white noise (seeds 0x1234567 / 0x7654321) x 0.1, then x 2.0 at 1 s, x 0.1 at 2 s', '-20 dB / +6 dB steps');
  }
  {
    const f = sec(3);
    const L = new Float32Array(f);
    const R = new Float32Array(f);
    for (let k = 0; k < 5; k++) {
      const p = sec(0.1 + k * 0.55);
      for (let i = 0; i < sec(0.4); i++) {
        const v = 1.6 * Math.exp(-i / sec(0.08)) * Math.sin((2 * Math.PI * 50 * i) / SR);
        L[p + i] = v;
        R[p + i] = v;
      }
    }
    await limCase('kick_like', f, [L, R], '50 Hz bursts x 1.6 with an 80 ms decay, every 0.55 s', 'transients');
  }
  {
    const f = sec(2);
    const b = sineBursts(f, [2.0], 1.2, 0.5, 220);
    for (let i = 0; i < f; i++) b[1][i] *= 0.1;
    await limCase('stereo_unbalanced', f, b, '220 Hz: L x 2.0, R x 0.2, 1.2 s from 0.05 s, then silence (release)', 'detector = max of channels');
  }
}

// ---------------------------------------------------------------------------
// source: AudioBufferSourceNode as engine.js Deck uses it, and the spin voices
// ---------------------------------------------------------------------------
async function suiteSource() {
  const bufSec = 2.5;
  const mk = (name, o) =>
    runCase('source', name, {
      frames: o.frames || sec(2),
      engineJs: 'AudioBufferSourceNode (as engine.js Deck._makeSource sets it: playbackRate.value = tempo, loop / loopStart / loopEnd)',
      graph: 'AudioBufferSourceNode(buffer = the input file) -> destination',
      inputDesc: `music-like test signal (110 Hz harmonics, 3520 / 3150 Hz sines, noise seed 0xABCDEF), ${o.bufRate || SR} Hz, ${o.bufSeconds || bufSec} s`,
      notes: o.notes || '',
      short: o.short,
      build: async (ctx, meta) => {
        const bufRate = o.bufRate || SR;
        const input = musicLike(sec(o.bufSeconds || bufSec, bufRate), bufRate);
        const src = ctx.createBufferSource();
        src.buffer = bufferFrom(ctx, input, bufRate);
        src.playbackRate.value = o.rate || 1;
        if (o.loop) {
          src.loop = true;
          src.loopStart = o.loop[0];
          src.loopEnd = o.loop[1];
        }
        src.connect(ctx.destination);
        src.start(0, o.offset || 0);
        meta.setup.push({
          node: 'AudioBufferSourceNode',
          bufferRate: bufRate,
          bufferFrames: input[0].length,
          playbackRate: o.rate || 1,
          loop: !!o.loop,
          loopStart: o.loop ? o.loop[0] : 0,
          loopEnd: o.loop ? o.loop[1] : 0,
          start: { when: 0, offset: o.offset || 0 }
        });
        const events = (o.events || []).map(([frame, rate]) =>
          at(frame, 'source.playbackRate.value', [rate], () => {
            src.playbackRate.value = rate;
          }));
        return { input, inputRate: bufRate, events };
      }
    });
  const rates = quick ? [0.5, 1.02, 1.6] : [0.5, 0.75, 0.9999, 1.02, 1.25, 1.6];
  for (const r of rates) await mk(`rate_${r}`, { rate: r, short: `rate ${r}` });
  await mk('rate_1_exact_copy', { rate: 1, short: 'rate 1: exact copy' });
  await mk('rate_1_fractional_offset', { rate: 1, offset: 0.123456789, short: 'start offset between samples' });
  await mk('filerate_44100_rate_1', { bufRate: 44100, rate: 1, short: '44.1 kHz buffer in a 48 kHz context' });
  await mk('filerate_44100_rate_1.06', { bufRate: 44100, rate: 1.06, short: '44.1 kHz buffer at rate 1.06' });
  await mk('loop_rate_1', { rate: 1, loop: [0.25037, 0.75011], offset: 0.3, frames: sec(2.5), short: 'loop seams between samples' });
  await mk('loop_rate_1.33', { rate: 1.33, loop: [0.25037, 0.75011], offset: 0.3, frames: sec(2.5), short: 'loop at rate 1.33' });
  await mk('loop_short_10ms', { rate: 1, loop: [1.0, 1.01], offset: 1.0, frames: sec(1), short: '10 ms loop' });
  await mk('play_past_the_end', { rate: 1.25, bufSeconds: 1.0, frames: sec(1.5), short: 'buffer end at rate 1.25' });
  await mk('tempo_change', {
    rate: 1, frames: sec(2), events: [[qframes(0.5), 1.06], [qframes(1.0), 0.94], [qframes(1.5), 1]],
    notes: 'engine.js Deck.setTempo sets source.playbackRate.value (k-rate: takes effect at the quantum)', short: 'setTempo steps'
  });
  // V.BRAKE / BACKSPIN: engine.js Deck.spinSound on a deck holding the buffer
  // (not playing), tapped at scrubIn (the deck's pre-TRIM voice).
  const spin = (name, kind, pos, tempo, stopAt) =>
    runCase('source', name, {
      frames: sec(2.2),
      engineJs: 'Deck.spinSound / stopSpinSound (src/js/engine.js)',
      graph: 'deck.spinSound voice (AudioBufferSourceNode on a slice, playbackRate ramp) -> scrubIn -> destination (tapped before TRIM)',
      inputDesc: 'music-like test signal, 48 kHz, 4 s (the deck buffer)',
      notes: `deck.loadTrack({buffer}), deck.offset = ${pos}, deck.tempo = ${tempo}, then deck.spinSound('${kind}') at frame 0`,
      short: `${kind} at ${pos} s${stopAt ? `, stopped at ${stopAt} s` : ''}`,
      build: async (ctx) => {
        const deck = new Deck(ctx, ctx.destination, 0);
        deck.dryOut.disconnect();
        deck.scrubIn.disconnect();
        deck.scrubIn.connect(ctx.destination);
        const input = musicLike(sec(4));
        deck.loadTrack({ buffer: bufferFrom(ctx, input) });
        deck.offset = pos;
        deck.tempo = tempo;
        const events = [at(0, 'deck.spinSound', [kind], () => deck.spinSound(kind))];
        if (stopAt) events.push(at(qframes(stopAt), 'deck.stopSpinSound', [], () => deck.stopSpinSound()));
        return { input, events };
      }
    });
  await spin('spin_vbrake', 'vbrake', 1.0, 1, 0);
  await spin('spin_vbrake_tempo_1.25', 'vbrake', 1.0, 1.25, 0);
  await spin('spin_backspin', 'backspin', 2.5, 1, 0);
  await spin('spin_backspin_stopped', 'backspin', 2.5, 1, 0.3);
}

// ---------------------------------------------------------------------------
// fx: every engine.js FxUnit type
// ---------------------------------------------------------------------------
const FX_TYPES = ['delay', 'echo', 'spiral', 'mtdelay', 'upecho', 'downecho', 'lowcut', 'pingpong', 'reverb',
  'flanger', 'phaser', 'pan', 'trans', 'filter', 'roll', 'robot', 'helix', 'crush'];
let fxImpulseSaved = false;
async function suiteFx() {
  const frames = sec(3);
  const fxCase = (type, level, beats, beatDur) =>
    runCase('fxunit', `${type}_l${level}_b${beats}${beatDur !== 0.5 ? `_bd${beatDur}` : ''}`, {
      frames,
      engineJs: 'FxUnit (src/js/engine.js)',
      graph: 'input -> unit.input -> (chain of the type) -> unit.wet (level, tau 20 ms) -> destination',
      inputDesc: 'impulse 0.9 at 0.05 s; noise burst +-0.5 0.5-0.6 s; 1-2 s: 440 / 660 Hz sines x 0.3 + noise 0.1 (seed 0x5EED); then silence',
      notes: 'The reverb impulse is the buffer engine.js handed to the ConvolverNode (makeImpulse(2.2, 2.5) from a seeded Math.random, ' +
        'memoized by engine.js across units): saved as fxunit/reverb_impulse.wav, raw (ConvolverNode normalize = true applies the Chromium ' +
        'normalization). Beat clock: beat 0 at frame 0; the LFOs are restarted at frame 0 by unit.alignTo(0) (engine.js fxTick), so a ' +
        'beat-locked LFO starts with phase 0 at frame 0.',
      short: `level ${level}, beats ${beats}, beatDur ${beatDur}`,
      build: async (ctx, meta) => {
        Math.random = xorshift(0xf00d);
        const unit = new FxUnit(ctx, ctx.destination);
        const input = fxInput(frames);
        playInto(ctx, input, unit.input);
        const calls = [
          ['setType', [type]],
          ['setBeatsMult', [beats]],
          ['setBeatDur', [beatDur]],
          ['setLevel', [level]],
          ['setEnabled', [true]],
          ['alignTo', [0]]
        ];
        const events = calls.map(([c, a]) => at(0, `unit.${c}`, a, () => unit[c](...a)));
        const files = {};
        if (!fxImpulseSaved || type === 'reverb') {
          const ir = unit.convolver.buffer;
          files['reverb_impulse.wav'] = [channelsOf(ir), ir.sampleRate];
          fxImpulseSaved = true;
        }
        meta.files.impulse = 'fxunit/reverb_impulse.wav';
        return { input, events, files };
      }
    });
  const levels = quick ? [1] : [0.4, 1];
  for (const t of FX_TYPES) for (const l of levels) await fxCase(t, l, 0.5, 0.5);
  if (!quick) {
    for (const t of ['echo', 'delay', 'pingpong', 'mtdelay']) {
      await fxCase(t, 1, 0.25, 0.5);
      await fxCase(t, 1, 1, 0.5);
    }
    for (const t of ['echo', 'flanger', 'trans', 'phaser', 'filter', 'pan']) await fxCase(t, 1, 0.5, 0.468);
  }
}

// ---------------------------------------------------------------------------
// color: the Color FX bus of engine.js AudioEngine (+ the per-deck noise)
// ---------------------------------------------------------------------------
async function suiteColor() {
  const frames = sec(3);
  for (const t of ['dubecho', 'hpfecho', 'lpfecho', 'bpfecho', 'crushecho', 'reverb', 'crush']) {
    await runCase('color', t, {
      frames,
      engineJs: 'AudioEngine Color FX (src/js/engine.js setColorType, _colorDefs, cReverb, cCrush)',
      graph: 'input -> engine.colorBus -> (color chain) -> colorWet (0.85) -> destination (tapped before fxReturn)',
      inputDesc: 'the fx input (impulse, noise burst, sines + noise, silence; seed 0x5EED)',
      notes: 'The 2.8 s "Space" impulse engine.js built (makeImpulse(2.8, 2.2), seeded Math.random, memoized) is saved as color/space_impulse.wav (raw; normalize = true).',
      short: t,
      build: async (ctx, meta) => {
        Math.random = xorshift(0xc0ffee);
        const engine = makeEngine(ctx);
        engine.limiter.disconnect();
        engine.colorWet.disconnect();
        engine.colorWet.connect(ctx.destination);
        const input = fxInput(frames);
        playInto(ctx, input, engine.colorBus);
        const events = [at(0, 'engine.setColorType', [t], () => engine.setColorType(t))];
        const files = {};
        if (t === 'reverb') files['space_impulse.wav'] = [channelsOf(engine.cReverb.buffer), engine.cReverb.buffer.sampleRate];
        meta.files.impulse = 'color/space_impulse.wav';
        return { input, events, files };
      }
    });
  }
  // "noise": white noise (the engine's own looped 2 s buffer) x amt^2 x 0.4 into deck 0's fader.
  const step = qframes(0.5);
  await runCase('color', 'noise', {
    frames: step * 5,
    engineJs: 'AudioEngine setColorType("noise") + setDeckColor (src/js/engine.js)',
    graph: 'engine.noiseSrc (looped 2 s buffer, started at 0) -> decks[0].noiseGain (amt^2 x 0.4, tau 10 ms) -> fader (0.7225) -> xf (1) -> dryOut -> destination',
    inputDesc: 'no input (silence): the noise is the engine\'s noise buffer, saved as noise_buffer.wav',
    notes: 'The engine noise buffer (2 s, seeded Math.random) is saved as color/noise_buffer.wav; it loops from frame 0.',
    short: 'setDeckColor(0) 0.5 1 -0.3 0',
    build: async (ctx, meta) => {
      Math.random = xorshift(0xc0ffee);
      const engine = makeEngine(ctx);
      engine.limiter.disconnect();
      const d0 = engine.decks[0];
      d0.dryOut.disconnect();
      d0.dryOut.connect(ctx.destination);
      const input = [new Float32Array(16), new Float32Array(16)];
      const events = [at(0, 'engine.setColorType', ['noise'], () => engine.setColorType('noise'))];
      [0.5, 1, -0.3, 0].forEach((v, i) => events.push(at(step * i, 'engine.setDeckColor', [0, v], () => engine.setDeckColor(0, v))));
      const nb = engine.noiseSrc.buffer;
      meta.files.noise = 'color/noise_buffer.wav';
      return { input, events, files: { 'noise_buffer.wav': [channelsOf(nb), nb.sampleRate] } };
    }
  });
}

// ---------------------------------------------------------------------------
// wsola: the real pitch-worklet.js in an AudioWorklet
// ---------------------------------------------------------------------------
async function suiteWsola() {
  const workletUrl = new URL('../../src/js/pitch-worklet.js', import.meta.url).href;
  const frames = sec(3);
  const wcase = (name, moves, short) =>
    runCase('wsola', name, {
      frames,
      engineJs: 'pitch-worklet.js (AudioWorkletNode "pitch-shift", options of engine.js _loadPitchWorklet)',
      graph: 'input -> AudioWorkletNode(pitch-shift: 1 input, 1 output, outputChannelCount [2], channelCount 2, explicit) -> destination',
      inputDesc: 'music-like test signal (110 Hz harmonics, 3520 / 3150 Hz sines, noise seed 0xABCDEF), 48 kHz',
      notes: 'ratio moves are engine.js _applyPitch calls: param("ratio").setTargetAtTime(r, t, 0.02), k-rate (one value per 128-frame quantum). Fixed latency 2647 frames.',
      short,
      build: async (ctx) => {
        await ctx.audioWorklet.addModule(workletUrl);
        const node = new AudioWorkletNode(ctx, 'pitch-shift', {
          numberOfInputs: 1,
          numberOfOutputs: 1,
          outputChannelCount: [2],
          channelCount: 2,
          channelCountMode: 'explicit'
        });
        node.connect(ctx.destination);
        const input = musicLike(frames);
        playInto(ctx, input, node);
        const ratio = node.parameters.get('ratio');
        const events = moves.map(([frame, r]) => at(frame, 'ratio.setTargetAtTime', [r, frame / SR, 0.02], () => ratio.setTargetAtTime(r, frame / SR, 0.02)));
        return { input, events };
      }
    });
  const consts = quick ? [0.5, 1, 1.8] : [0.5, 0.75, 0.9439, 1, 1.0595, 1.25, 1.5, 1.8];
  for (const r of consts) await wcase(`ratio_${r}`, [[0, r]], `ratio ${r}`);
  await wcase('ratio_steps', [[0, 1], [qframes(0.5), 1.2], [qframes(1.0), 0.8], [qframes(1.5), 1.06], [qframes(2.0), 1]], 'ratio 1 1.2 0.8 1.06 1');
  await wcase('keylock_tempo_1.06', [[0, 1 / 1.06]], 'keylock at tempo 1.06 (ratio 1/1.06)');
}

// ---------------------------------------------------------------------------
// decode: decodeAudioData of generated files at the context rate (the proxy's
// shim decodes with an OfflineAudioContext(2, 1, deviceRate))
// ---------------------------------------------------------------------------
async function suiteDecode() {
  const files = [
    ['wav16_44100_stereo', 44100, 2, 's16'],
    ['wav24_48000_stereo', 48000, 2, 's24'],
    ['wavf32_96000_stereo', 96000, 2, 'f32'],
    ['wav16_22050_mono', 22050, 1, 's16'],
    ['wav16_48000_6ch', 48000, 6, 's16']
  ];
  for (const [name, rate, nch, fmt] of files) {
    await runCase('decode', name, {
      frames: 1,
      engineJs: 'BaseAudioContext.decodeAudioData (Chromium FFmpeg decoder + resampler)',
      graph: 'generated file -> OfflineAudioContext(2, 1, 48000).decodeAudioData -> AudioBuffer (the output; channels as decoded)',
      inputDesc: `${fmt} WAV, ${rate} Hz, ${nch} channel(s), 2 s: music-like signal (channel c: L for even c, R for odd c, x (1 - 0.1 c))`,
      notes: 'The output has the decoded channel count (the engine folds to stereo, SPEC.md §5) and the context rate (resampled by Chromium).',
      short: `${fmt} ${rate} Hz ${nch} ch`,
      build: async (ctx, meta) => {
        const base = musicLike(sec(2, rate), rate);
        const chans = [];
        for (let c = 0; c < nch; c++) chans.push(base[c & 1].map((v) => v * (1 - 0.1 * c)));
        const bytes = wav(chans, rate, fmt);
        const decoded = await new OfflineAudioContext(2, 1, SR).decodeAudioData(bytes.slice().buffer);
        meta.decoded = { channels: decoded.numberOfChannels, sampleRate: decoded.sampleRate, frames: decoded.length };
        meta.source = { format: fmt, rate, channels: nch, frames: chans[0].length };
        // The render itself is a 1-frame stub: the golden IS the decoded buffer.
        decodedResult = decoded;
        return { input: chans, inputRate: rate, inputFile: { name: `${name}.input.wav`, bytes }, events: [] };
      }
    });
  }
  // AAC through WebCodecs (when this Chromium can encode it), in an ADTS stream.
  if (!only.length || only.includes('decode')) await decodeAac();
}

let decodedResult = null;
// runCase writes the render; for decode cases the decoded buffer replaces it.
const runCaseRender = runCase;

async function decodeAac() {
  if (typeof AudioEncoder === 'undefined') {
    await window.goldens.log('  decode/aac: skipped (no WebCodecs AudioEncoder)');
    return;
  }
  const config = { codec: 'mp4a.40.2', sampleRate: 48000, numberOfChannels: 2, bitrate: 160000 };
  let support = null;
  try {
    support = await AudioEncoder.isConfigSupported(config);
  } catch {
    support = null;
  }
  if (!support || !support.supported) {
    await window.goldens.log('  decode/aac: skipped (this Chromium cannot encode AAC)');
    return;
  }
  const frames = sec(2);
  const sig = musicLike(frames);
  const packets = [];
  const enc = new AudioEncoder({
    output: (chunk) => {
      const b = new Uint8Array(chunk.byteLength);
      chunk.copyTo(b);
      packets.push(b);
    },
    error: (e) => errors.push(`decode/aac encoder: ${e}`)
  });
  enc.configure({ ...config, aac: { format: 'adts' } });
  const planar = new Float32Array(frames * 2);
  planar.set(sig[0], 0);
  planar.set(sig[1], frames);
  enc.encode(new AudioData({ format: 'f32-planar', sampleRate: 48000, numberOfFrames: frames, numberOfChannels: 2, timestamp: 0, data: planar }));
  await enc.flush();
  enc.close();
  let total = 0;
  for (const p of packets) total += p.length;
  const adts = new Uint8Array(total);
  let o = 0;
  for (const p of packets) {
    adts.set(p, o);
    o += p.length;
  }
  const isAdts = adts.length > 2 && adts[0] === 0xff && (adts[1] & 0xf0) === 0xf0;
  if (!isAdts) {
    await window.goldens.log('  decode/aac: skipped (the encoder did not produce ADTS)');
    return;
  }
  await runCase('decode', 'aac_48000_stereo', {
    frames: 1,
    engineJs: 'BaseAudioContext.decodeAudioData of an ADTS AAC stream encoded by WebCodecs (AAC-LC 160 kb/s)',
    graph: 'ADTS file -> OfflineAudioContext(2, 1, 48000).decodeAudioData -> AudioBuffer',
    inputDesc: 'music-like signal 48 kHz stereo 2 s, encoded to AAC (encoder delay / priming included: what the shadow decoder measures)',
    notes: 'The source signal is saved as aac_48000_stereo.source.wav.',
    short: 'AAC (ADTS)',
    build: async (ctx, meta) => {
      const decoded = await new OfflineAudioContext(2, 1, SR).decodeAudioData(adts.slice().buffer);
      meta.decoded = { channels: decoded.numberOfChannels, sampleRate: decoded.sampleRate, frames: decoded.length };
      decodedResult = decoded;
      return { input: sig, inputFile: { name: 'aac_48000_stereo.input.aac', bytes: adts }, files: { 'aac_48000_stereo.source.wav': [sig, 48000] }, events: [] };
    }
  });
}

// ---------------------------------------------------------------------------
async function main() {
  const t0 = performance.now();
  // decode cases: write the decoded buffer instead of the 1-frame render
  const origStartRendering = OfflineAudioContext.prototype.startRendering;
  OfflineAudioContext.prototype.startRendering = async function () {
    const r = await origStartRendering.call(this);
    if (decodedResult) {
      const d = decodedResult;
      decodedResult = null;
      return d;
    }
    return r;
  };
  void runCaseRender;
  for (const [name, fn] of [['strip', suiteStrip], ['master', suiteMaster], ['limiter', suiteLimiter], ['source', suiteSource],
    ['fxunit', suiteFx], ['color', suiteColor], ['wsola', suiteWsola], ['decode', suiteDecode]]) {
    if (only.length && !only.includes(name)) continue;
    await window.goldens.log(`${name}:`);
    await fn();
  }
  await window.goldens.done({ cases: caseCount, errors, seconds: (performance.now() - t0) / 1000 });
}

main().catch(async (e) => {
  errors.push(String(e && e.stack ? e.stack : e));
  await window.goldens.done({ cases: caseCount, errors });
});
